-- SMARTSTOCK / Supabase PostgreSQL schema
create extension if not exists pgcrypto;

create table if not exists public.categories (
  category_id bigint generated by default as identity primary key,
  category_name text not null unique,
  description text not null default '',
  created_at timestamptz not null default now()
);
create table if not exists public.suppliers (
  supplier_id bigint generated by default as identity primary key,
  supplier_name text not null unique,
  phone text not null default '', email text not null default '', address text not null default '',
  created_at timestamptz not null default now()
);
create table if not exists public.products (
  product_id bigint generated by default as identity primary key,
  product_name text not null, category_id bigint not null references public.categories(category_id), supplier_id bigint not null references public.suppliers(supplier_id),
  sku text not null unique, unit_price numeric(12,2) not null check (unit_price >= 0), stock_qty integer not null default 0 check (stock_qty >= 0), reorder_level integer not null default 0 check (reorder_level >= 0),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.purchases (
  purchase_id bigint generated by default as identity primary key, supplier_id bigint not null references public.suppliers(supplier_id), purchase_date timestamptz not null default now(), invoice_no text not null, notes text not null default ''
);
create table if not exists public.purchase_items (
  purchase_item_id bigint generated by default as identity primary key, purchase_id bigint not null references public.purchases(purchase_id) on delete cascade, product_id bigint not null references public.products(product_id), quantity integer not null check (quantity > 0), cost_price numeric(12,2) not null check (cost_price >= 0)
);
create table if not exists public.sales (
  sale_id bigint generated by default as identity primary key, sale_date timestamptz not null default now(), customer_name text not null default 'Walk-in customer', payment_method text not null check (payment_method in ('Cash','Card','UPI','Other')), notes text not null default ''
);
create table if not exists public.sale_items (
  sale_item_id bigint generated by default as identity primary key, sale_id bigint not null references public.sales(sale_id) on delete cascade, product_id bigint not null references public.products(product_id), quantity integer not null check (quantity > 0), selling_price numeric(12,2) not null check (selling_price >= 0)
);
create table if not exists public.stock_movements (
  movement_id bigint generated by default as identity primary key, product_id bigint not null references public.products(product_id), movement_type text not null check (movement_type in ('OPENING STOCK','PURCHASE','SALE','RESTOCK','ADJUSTMENT')), quantity_change integer not null check (quantity_change <> 0), reference_type text not null default 'DEMO', reference_id text, movement_date timestamptz not null default now(), remarks text not null default ''
);
create index if not exists products_category_idx on public.products(category_id);
create index if not exists products_supplier_idx on public.products(supplier_id);
create index if not exists movements_product_date_idx on public.stock_movements(product_id, movement_date desc);

create or replace function public.restock_product(p_product_id bigint, p_quantity integer, p_reference text default 'RESTOCK') returns void language plpgsql security invoker as $$
declare v_name text; begin if p_quantity is null or p_quantity <= 0 then raise exception 'Restock quantity must be positive'; end if; select product_name into v_name from public.products where product_id=p_product_id for update; if not found then raise exception 'Product not found'; end if; update public.products set stock_qty=stock_qty+p_quantity, updated_at=now() where product_id=p_product_id; insert into public.stock_movements(product_id,movement_type,quantity_change,reference_type,reference_id,remarks) values(p_product_id,'RESTOCK',p_quantity,'DEMO',p_reference,'Restock from SMARTSTOCK'); end; $$;

create or replace function public.record_sale(p_customer_name text, p_payment_method text, p_product_id bigint, p_quantity integer, p_selling_price numeric) returns bigint language plpgsql security invoker as $$
declare v_stock integer; v_sale_id bigint; begin if p_quantity is null or p_quantity <= 0 then raise exception 'Sale quantity must be positive'; end if; select stock_qty into v_stock from public.products where product_id=p_product_id for update; if v_stock is null then raise exception 'Product not found'; end if; if v_stock < p_quantity then raise exception 'Insufficient stock: % available', v_stock; end if; insert into public.sales(customer_name,payment_method) values(coalesce(nullif(p_customer_name,''),'Walk-in customer'),p_payment_method) returning sale_id into v_sale_id; insert into public.sale_items(sale_id,product_id,quantity,selling_price) values(v_sale_id,p_product_id,p_quantity,p_selling_price); update public.products set stock_qty=stock_qty-p_quantity, updated_at=now() where product_id=p_product_id; insert into public.stock_movements(product_id,movement_type,quantity_change,reference_type,reference_id,remarks) values(p_product_id,'SALE',-p_quantity,'SALE',v_sale_id::text,'Sale recorded atomically'); return v_sale_id; end; $$;

alter table public.categories enable row level security; alter table public.suppliers enable row level security; alter table public.products enable row level security; alter table public.purchases enable row level security; alter table public.purchase_items enable row level security; alter table public.sales enable row level security; alter table public.sale_items enable row level security; alter table public.stock_movements enable row level security;
-- Anonymous college demo policies. Replace with authenticated policies before production use.
do $$ begin
  create policy "demo read categories" on public.categories for select to anon, authenticated using (true);
  create policy "demo read suppliers" on public.suppliers for select to anon, authenticated using (true);
  create policy "demo read products" on public.products for select to anon, authenticated using (true);
  create policy "demo write products" on public.products for all to anon, authenticated using (true) with check (true);
  create policy "demo read transactions" on public.purchases for select to anon, authenticated using (true);
  create policy "demo read purchase items" on public.purchase_items for select to anon, authenticated using (true);
  create policy "demo read sales" on public.sales for select to anon, authenticated using (true);
  create policy "demo read sale items" on public.sale_items for select to anon, authenticated using (true);
  create policy "demo read movements" on public.stock_movements for select to anon, authenticated using (true);
exception when duplicate_object then null; end $$;
